# -*- coding: utf-8 -*-
"""矛盾驱动补盲 · 批次C13（v11 新域 7 簇+直答：职场PUA/身材焦虑/公共文明/教育惩戒/考研考公/农药残留/老旧小区）"""
def patch(path):
    src = open(path, encoding="utf-8").read()
    anchor_c = '    "注意机制": ["注意机制", "选择性注意", "分散注意", "什么是注意机制"],'
    new_c = '''    "职场PUA": ["老板总爱画饼", "画饼", "职场PUA", "PUA", "真心栽培",
              "分辨", "领导批评", "当众批评", "玻璃心"],
    "身材焦虑": ["身材焦虑", "胖一点", "不自律", "别人都说我胖", "该减肥",
              "减肥", "健康地管理身材", "体重", "管理身材"],
    "公共文明": ["熊孩子", "高铁", "孩子哭闹", "哭闹", "孩子还小", "忍忍",
              "家长沟通", "公共场所的边界", "公共场合", "太安静", "太压抑"],
    "教育惩戒": ["不打不成器", "讲道理没用", "讲道理", "打孩子", "家暴",
              "管教", "无法无天", "立规矩", "不打骂", "惩罚",
              "伤害的边界"],
    "考研考公": ["考研考公", "考研", "考公", "考不上研", "科研", "实业",
              "没上岸", "上岸", "稳定有什么不好", "就业", "考了几年"],
    "农药残留": ["农药残留", "农药", "有机食品", "有机", "不打药", "打药",
              "产量", "贵得有道理", "吃得安全", "实惠", "种地"],
    "老旧小区": ["老小区加装电梯", "加装电梯", "电梯", "一楼", "反对装电梯",
              "装电梯", "拆了重建", "改造", "老旧小区", "拆迁"],'''
    assert anchor_c in src, "cluster anchor missing"
    src = src.replace(anchor_c, new_c + "\n    " + anchor_c, 1)

    anchor_d = '    "注意机制": "注意机制是认知资源的选择性分配——选择性注意（聚焦）/分散注意（多任务）/持续注意；对应CSPMN只匹配激活条件空间",'
    new_d = '''    "职场PUA": "老板画饼、当众贬低、骂你是为你好，是『管理手段』vs『人格伤害』的矛盾——画饼（承诺不兑现）是激励手段的滥用，PUA（打压自尊让你不敢走）是控制手段，两者的区别在『目的』：栽培你是让你成长（给你机会/反馈/资源），PUA是让你离不开（否定你/让你自我怀疑/让你感激他）。真相：①老板为什么总画饼——画饼是低成本激励（不花一分钱让你加班/卖命），『明年给你升职』『做完这个项目分你股份』——部分是真规划（小公司确实没现钱），部分是套路（从不兑现/模糊承诺），分辨看历史：他兑现过几次？②被领导当众批评是我玻璃心吗——分两种：就事论事（指出问题+教你怎么改）=专业反馈，该听；人身攻击（贬低能力/人格/当众羞辱）=越界，不是你的问题——『当众批评』本身就不专业（好的管理者私下说重话，公开说轻话）；③领导严格要求有错吗——没错：严格（标准高）和PUA（贬低人）是两回事，高标准+给支持=栽培，高标准+不给资源+只骂人=消耗；④骂你是为你好对吗——不对：批评和辱骂有本质区别（批评讲事实，辱骂讲情绪），『为你好』是施暴者的万能借口，真为你好的人不会用伤害你的方式。怎么应对：①识别信号——画饼不兑现（连续2次以上）、否定式沟通（你不行/离开这里没人要你）、制造愧疚（我为你付出多少）、切断你的人际（别跟同事走太近）——中3条以上=职场PUA；②自保——工作成果留痕（邮件/文档，避免背锅）、保持竞争力（外面市场价心里有数，不怕走）、不自我怀疑（他的否定是他的控制手段，不是你的真实价值）；③反击或离开——收集证据（录音/截图，职场霸凌可投诉）、找HR/上级（如果公司文化正常）、最有效的反击是『成长到随时能走』（能力才是底气）；④健康边界——工作关系是价值交换不是情感绑架，老板不是爹妈，『感恩』不等于『服从一切』。核心：栽培让你变强，PUA让你变弱——看方向就知道是哪种",
    "身材焦虑": "别人都说我胖、该不该减肥，是『社会标准』vs『身体健康』的矛盾——身材标准是社会的（白幼瘦/腹肌/马甲线，随时代变的：唐朝以胖为美），身体健康是医学的（BMI/体脂/指标），该不该减不是看『别人怎么说』是看『身体需要什么』。真相：①为什么越来越多人身材焦虑——三重推手：社交媒体（精修图/滤镜制造身材幻象，现实中没人长那样）、审美单一化（白幼瘦被当唯一标准）、商业利益（身材焦虑=减肥产品/医美/健身课的生意，让你觉得自己不够好才能卖你东西）；②胖一点就是不自律吗——不是：体重受基因（代谢率先天不同）、激素（甲状腺/胰岛素）、疾病（多囊/甲减）、药物（激素药）影响，『胖=懒=不自律』是粗暴归因（有人狂吃不胖有人喝水利水），自律是『管理自己』不是『长成某种身材』；③减肥是为了健康有错吗——没错：医学标准下超重（BMI>24）/肥胖（BMI>28）确实增加三高风险（高血压/糖尿病/心血管），『为健康减重』完全正确——但要分清『健康减重』（医生/营养师指导，减到健康范围）和『焦虑减肥』（追求越瘦越好，节食到厌食）；④别人都说我胖该减吗——先看数据：BMI和腰围（男<90cm/女<85cm）在健康范围就不用为他人眼光减，别人说什么不是医学诊断——『为别人的嘴减肥』是交智商税，『为自己的健康管理』才是正事。怎么健康管理：①标准——体检指标（血糖/血脂/血压）比体重秤数字重要，肌肉比体重重要（同样体重，肌肉多的人更健康）；②方法——均衡饮食（七分饱/少油盐糖/蛋白质足量）+ 规律运动（每周150分钟中等强度）+ 充足睡眠（睡不好影响代谢），『少吃多动』是原理不是方法（节食会反弹，改变习惯才持久）；③心态——接受『健康体重是个范围不是定点』，体重波动正常（水分/生理期），别每天称体重（焦虑放大器），看长期趋势；④反焦虑——取关制造焦虑的账号（精修图不是现实），『悦己』优先于『悦人』，健康的身材观：强壮/有活力/能吃能睡，比『瘦』值钱。核心：身体是你的，标准是医生的——别人说的不算，指标说了算",
    "公共文明": "高铁上熊孩子哭闹、公共场所的边界，是『个人自由』vs『公共安宁』的矛盾——孩子的哭闹不是恶意（孩子控制不了），但公共场所是共享的（别人的安静/休息权利也该被尊重），矛盾在『家长管不管』：不管=把孩子的自由建立在别人痛苦上，管=家长辛苦但大家舒心。真相：①为什么高铁上总有熊孩子——两个『总』：孩子天性（高铁密闭4小时，孩子无聊/烦躁/难受就会闹，这不是家教问题是人性问题）＋家长失职（不管不问/让孩子看手机外放/任其踢椅背）——『熊孩子』背后是『熊家长』（孩子闹是正常的，家长不管才不正常）；②公共场合孩子哭闹该不该管——该引导不该打骂：小月龄婴儿哭（生理需要）旁人该理解（谁都有孩子），大孩子撒泼（要东西/无理取闹）家长该管教（带离现场/安抚/讲规则）——『管』是教育不是压制（孩子需要学『公共场合的规则』）；③孩子还小忍忍不行吗——『还小』是解释不是理由：孩子小（不懂事）是事实，但正因为小才要教（3岁立规矩不早），『忍忍』把教育责任推给别人（别人没义务替你忍），而且『小』有极限（5岁哭闹和2岁哭闹性质不同）；④公共场合太安静是不是太压抑——不是对立：公共场合不是图书馆（可以说话/孩子可以玩），也不是游乐场（不能大喊/奔跑/外放），边界是『不影响他人』——孩子玩闹可以，尖叫不行；说话可以，外放不行——这是文明不是压抑。怎么处理：①家长——出行准备（玩具/零食/动画片提前下载）、孩子闹了先安抚（共情+转移注意）、实在控制不住带离车厢（走廊/车厢连接处）、主动致歉（『对不起打扰了』一句能化解大半敌意）；②他人——理解小婴儿（生理哭闹没办法，家长也在努力）、对大孩子撒泼不直接骂孩子（骂家长/叫乘务员更有效）、善意提醒（『孩子踢到我椅背了』比『管好你孩子』中听）；③社会——高铁设亲子车厢/静音车厢（分流需求）、公共空间儿童设施（母婴室/游乐角），环境友好比指责有效。核心：公共文明的边界是『你的自由到我的安宁为止』——孩子要有童年，别人也要有清净，中间靠家长的管教和大家的理解",
    "教育惩戒": "孩子不打不成器、讲道理没用，是『立规矩』vs『不伤害』的矛盾——孩子需要规则（没有边界的孩子没有安全感），但打骂是『立规矩』最偷懒也最伤人的方式（孩子学到的是『谁力气大听谁的』不是规则本身）。真相：①孩子不打不成器吗——不是：『打出来的乖』是恐惧（怕挨打才听话，家长不在就原形毕露），『教出来的乖』是内化（懂规则，家长不在也遵守）——打骂的即时效果（立竿见影）掩盖了长期代价（亲子关系损伤/孩子学会用暴力解决问题/自尊受损），不打也能成器（全世界教育发达地区都不靠打）；②为什么讲道理没用——因为『讲道理』用错了场合：孩子在情绪里（哭闹/发脾气）时听不进任何道理（大脑被情绪接管，道理进不去），讲道理要在平静时（事后再谈），而且道理要配后果（光说『不能打人』没有『打了要道歉/承担后果』，孩子没有记忆点）；③打孩子是家暴还是管教——法律上：造成身体伤害（淤青/红肿/就医）就是家暴（反家暴法保护未成年人），教育意义上：『打』是家长情绪失控的表现（孩子不听话触发你的怒气），不是教育方法——『我打你是为你好』是自我合理化（真为孩子好就不会用最伤关系的方式）；④完全不管孩子不就无法无天——完全不管（溺爱/放任）确实不行（孩子需要边界），但『不管』和『不打』不是一回事：立规矩（明确的规则+一致的执行+后果承担）不需要打骂——孩子需要的是『确定的规则』不是『恐惧的拳头』。怎么立规矩：①规则明确——3-5条核心规则（不打人/不撒谎/自己的事自己做），全家一致（爸爸说不行的妈妈别拆台），说清楚为什么（『过马路要牵手，因为车不会躲你』）；②后果承担——违反规则的自然/逻辑后果（玩具乱扔=玩具收走一周/打了人要道歉+补偿），后果要提前说+执行坚决+不附加羞辱（『你看你活该』是羞辱不是教育）；③情绪管理——孩子哭闹时先处理情绪（抱一抱/等平静）再处理事情（『我知道你生气，但规则不能改』），家长自己先别失控（孩子是镜子，你吼他他就学吼）；④表扬与修复——做对了明确表扬（『你今天自己收拾了玩具，真负责』），做错了修复关系（打骂之后道歉：『爸爸刚才太凶了，对不起，但打人不对』——示范道歉也是教育）。核心：惩罚的目的是让孩子学会，不是让孩子害怕——不打骂也能立规矩，区别在你是『管教』还是『出气』",
    "考研考公": "越来越多人考研考公、考不上研就是失败吗，是『稳定追求』vs『竞争内卷』的矛盾——考公考研热是年轻人对不确定性的防御（就业难/35岁危机/私企不稳，体制内稳定），但千军万马挤独木桥本身就是内卷（投入巨大/上岸率低/错过其他可能）。真相：①为什么越来越多人考研考公——结构性原因：就业市场收缩（企业招人少/裁员多）、体制优势显现（稳定/福利/养老金/社会地位）、家庭预期（父母眼中的正经工作）——这是理性选择（对风险的理性防御），不是年轻人躺平；②考不上研就是失败吗——不是：考研是路径不是终点（考不上=这条路没走通，不代表人不行），而且『考』本身就是巨大投入（一年时间/脱产成本/心理压力），失败的是这次考试不是这个人——多少人二战三战上岸后发现不喜欢科研（沉没成本），考不上可能是『及时止损』；③都去考公谁搞科研做实业——这是结构性隐忧：人才过度流向体制内，科研/实业的优秀人才被抽走（社会的损失），但个体没有错（谁都会选对自己有利的），该反思的是『为什么科研/实业留不住人』（待遇/稳定性/尊重不够）——治本是把体制外的路修好，不是指责考公的人；④稳定有什么不好——稳定本身没错（生活可预期/家庭安稳），问题是『为稳定付出多大代价』：考公二战三战四战（时间成本/与市场脱节）、考上后一眼望到头（如果讨厌体制内生活，稳定是牢笼）——稳定是选择不是信仰，适合稳定的人稳定是幸福，不适合的人稳定是消耗。怎么选：①先想清楚要什么——求稳（家庭/性格适合体制）→考公考编；求发展（想做事/要空间）→就业/创业/考研深造——没有对错只有匹配；②算成本——考研（时间+费用+机会成本）vs 直接就业（经验+收入+试错），脱产二战前先问『我能接受最坏结果吗』；③考了几年没上岸——设止损线（2次=重新评估），『全职考公多年』的机会成本极高（同龄人已有5年经验），边工作边考/转赛道都是选择，执念不是坚持（坚持是看到希望，执念是看不见还撞墙）；④心态——人生是长期游戏，25岁的『失败』（没上岸）和30岁的『成功』（找到适合的路）不矛盾，条条大路通罗马的前提是『你在走路不是站在原地焦虑』。核心：考研考公是好选择之一，不是唯一答案——选之前算清成本，选之后接受结果，别让『别人都在考』替你决定人生",
    "农药残留": "蔬菜水果都有农药、有机食品太贵，是『吃得安全』vs『生产成本』的矛盾——不打药菜被虫吃光（产量低/卖相差），打药有残留（短期毒性/长期风险），有机（不打农药）贵在成本（人工除虫/产量低/认证费），矛盾是：安全要花钱，便宜有风险，怎么在中间找平衡。真相：①蔬菜水果都有农药残留吗——大概率有但不等于有害：中国农产品农药残留合格率近年都在97%以上（国家抽检数据），『有残留』和『超标有害』是两回事（残留量低于安全标准=可安全食用），该担心的是『小摊贩/来源不明的菜』（没检测），正规市场/超市的菜有抽检保障；②不买有机食品就不安全吗——不是：有机（不施化学农药）和常规（规范用药）的食品安全差异远小于价格差异（有机贵3-5倍），常规种植只要『规范用药+过了安全间隔期+检测合格』就安全——『有机=安全』是营销话术（有机也可能有虫害污染/微生物风险），常规菜的农药残留清洗后远低于标准；③种地不打药产量够吗——不够：不打药病虫害损失可达30-50%（虫吃/病害/霉变），全球粮食安全靠农药（没有农药，三分之一粮食会损失），农药是农业必需（关键在『科学用药』：用低毒药/按剂量/按安全间隔期），『零农药』是理想不是现实；④有机食品贵得有道理吗——有：有机生产成本高（人工除虫/有机肥贵/产量低30%+认证费用），贵有贵的道理，但『贵=更好』要打问号（有机的营养价值与常规差别很小，主要差别在『农残更少/生产方式环保』）——为健康买有机（预算够）可以，为营养买有机（多花钱）没必要。怎么吃得安全又实惠：①来源——优先正规渠道（超市/农贸市场/有检测的市场），不买路边无来源的『超便宜菜』（便宜异常必有蹊跷）；②清洗——流水冲洗+浸泡（清水泡10分钟/小苏打或盐水泡去农残）+去皮（表皮农残最多）+焯水（高温降解部分农残）——这些操作能去除大部分表面残留；③多样化——别长期吃单一蔬菜（分散风险），当季蔬菜（当季病虫害少用药少）；④理性买有机——预算够给家人（尤其孕妇/婴幼儿）买有机叶菜（叶菜农残风险高于根茎类），预算有限就『常规+认真清洗』（清洗后的常规菜足够安全）；⑤心态——农残风险远小于盐油糖/烟酒/熬夜（这些才是健康大头），别为『零残留』焦虑（绝对零残留不存在，安全标准以内就可以）。核心：吃得安全的关键是『规范+清洗』不是『只买有机』——合格菜认真洗，比恐慌性高价消费更实在",
    "老旧小区": "老小区加装电梯难、改造有分歧，是『居住改善』vs『利益分配』的矛盾——高层老人盼电梯（爬楼难/出行不便），一楼不想要（采光/噪音/贬值），装不装、钱怎么分，是典型的多方利益博弈（每户的利益诉求都正当）。真相：①为什么加装电梯这么难——核心是利益分歧：高层（尤其老人）刚需（爬不动楼）vs 一楼（采光遮挡/噪音/隐私/房价相对贬值）vs 中低层（用不上还要出钱）——每户都合理，但没有让所有人都满意的方案（电梯不是公共品，是部分人受益的改造）；②一楼凭什么反对——凭『他的损失是真的』：电梯井挡采光（冬天更暗）、运行噪音（睡眠影响）、人流经过（隐私）、老房子一楼本来好卖（有电梯后高层升值一楼贬值）——不是一楼自私，是『受益者出钱、受损者被补偿』的原则没落实；③装电梯的钱该谁出——原则：受益者多出/受损者补偿：按楼层分摊（高层多出/低层少出/一楼不出甚至得补偿），政府补贴一部分（很多城市有加装电梯补贴），『一楼也分摊』是制造矛盾；④老小区拆了重建不更好吗——理想美好现实难：拆迁成本极高（原址安置/补偿），绝大多数老小区只能『改造』（加装电梯/外立面/管道/绿化）——『拆了重建』是少数（危房/区位价值高），多数是『缝缝补补又几年』（改造是现实的唯一答案）。怎么让大家都满意：①方案设计——电梯选型（观光梯/连廊设计减少遮挡）、位置优化（避开卧室窗户）、降噪措施（隔音罩），用技术把一楼损失降到最低；②补偿机制——一楼免出资+适当补偿（协商/政府补贴/高层分担），『受损补偿』写在协议里（白纸黑字比口头承诺可靠）；③议事规则——一栋楼一策（不搞一刀切，每栋楼居民自己协商）、双2/3同意（物权法规定：专有部分面积2/3+人数2/3同意可加装）、不同意的诉求要听到（不是多数压倒少数，是协商出方案）；④改造整体观——加装电梯不是孤立工程（配套：楼道翻新/无障碍/适老化），把改造做成『整栋楼都受益』（一楼也沾光：外立面/门禁/公共区域升级），利益共同体比零和博弈容易谈。核心：老旧小区改造的钥匙是『让受损者不吃亏』——受益的出钱、受损的补偿、政府出政策，谈得拢的方案不是谁说服谁，是每个人都觉得自己没亏",
    "注意机制": "注意机制是认知资源的选择性分配——选择性注意（聚焦）/分散注意（多任务）/持续注意；对应CSPMN只匹配激活条件空间",'''
    assert anchor_d in src, "daily anchor missing"
    src = src.replace(anchor_d, new_d, 1)
    open(path, "w", encoding="utf-8").write(src)
    print("patched")

